const input = $input.all()[0].json;
const investors = input.investors || [];
const founderProfile = input.founder_profile || {};

if (!investors.length) {
  return [{ json: { status: 'error', error: 'No investors provided', connected_founders: [] } }];
}

return investors.map(inv => ({
  json: {
    investor: inv,
    founder_profile: founderProfile
  }
}));

const response = $json;
const investorName = $input.item.json?.investor?.name || 'Unknown';

let founders = [];
if (response?.founders) founders = response.founders;
else if (response?.result?.founders) founders = response.result.founders;
else if (response?.data?.founders) founders = response.data.founders;

return {
  json: {
    investor_name: investorName,
    found_founders: (founders || []).map(f => ({
      name: f.name || 'Unknown',
      title: f.title || '',
      company: f.company || '',
      profile_url: f.profile_url || '',
      connected_via_investor: investorName
    }))
  }
};

const items = $input.all();
const founderMap = new Map();

for (const item of items) {
  const investorName = item.json.investor_name;
  const founders = item.json.found_founders || [];

  for (const f of founders) {
    const key = (f.profile_url || `${f.name}_${f.company}`).toLowerCase();

    if (founderMap.has(key)) {
      const existing = founderMap.get(key);
      if (!existing.connected_investors.includes(investorName)) {
        existing.connected_investors.push(investorName);
        existing.mutual_connections_count = existing.connected_investors.length;
      }
    } else {
      founderMap.set(key, {
        name: f.name,
        title: f.title,
        company: f.company,
        profile_url: f.profile_url,
        connected_investors: [investorName],
        mutual_connections_count: 1
      });
    }
  }
}

const sortedFounders = Array.from(founderMap.values())
  .sort((a, b) => b.mutual_connections_count - a.mutual_connections_count);

return [{
  json: {
    status: 'success',
    connected_founders: sortedFounders,
    count: sortedFounders.length
  }
}];
